SourceCode.Declaration:
[DataContractAttribute]
class HSMobileOpsSetModulePermissionRequest
{
    DataAreaId dataAreaId;
    str        actingUserName;
    str        targetUserName;
    str        module;
    boolean    isAllowed;

}

Method.Source:
[DataMemberAttribute('DataAreaId')]
public DataAreaId parmDataAreaId(DataAreaId _value = dataAreaId)
{
    dataAreaId = _value;
    return dataAreaId;
}

/// <summary>
/// Who is making this change - re-checked server-side for IsSupervisor before anything is
/// written. Never trusted from a client-supplied boolean: the device's own idea of whether
/// it is signed in as a supervisor is exactly the thing a modified client could lie about,
/// so HSMobileOpsUserService::setModulePermission looks this user up itself.
/// </summary>
[DataMemberAttribute('ActingUserName')]
public str parmActingUserName(str _value = actingUserName)
{
    actingUserName = _value;
    return actingUserName;
}

/// <summary>
/// Whose permission is being changed. May be the same as ActingUserName, though the Admin
/// Center has no reason to offer that - nothing stops a supervisor from blocking their own
/// access, and nothing needs to.
/// </summary>
[DataMemberAttribute('TargetUserName')]
public str parmTargetUserName(str _value = targetUserName)
{
    targetUserName = _value;
    return targetUserName;
}

/// <summary>
/// An HSMobileOpsModule element name - see HSMobileOpsModulePermission::parmModule for the
/// same convention on the read side.
/// </summary>
[DataMemberAttribute('Module')]
public str parmModule(str _value = module)
{
    module = _value;
    return module;
}

[DataMemberAttribute('IsAllowed')]
public boolean parmIsAllowed(boolean _value = isAllowed)
{
    isAllowed = _value;
    return isAllowed;
}
